// -- HarnessProjector interface + writeGenerated helper.
//
// This is the single extensibility contract: every harness adds one projector
// and registers it.  No global registry, no extension-type machinery.

import { mkdirSync, writeFileSync, readFileSync, existsSync } from "node:fs";
import { join } from "node:path";

export const BANNER = `// This file was auto-generated by tools/harness/sync.ts.
// Do not edit — changes will be overwritten on the next sync.\n`;

export interface NativeArtifact {
  path: string;   // relative to repo root, e.g. ".mcp.json"
  content: string;
}

/**
 * A projector owns a single harness's native files.
 * reserved[] lists paths this harness OWNS — sync never clobbers them.
 */
export interface HarnessProjector {
  id: string;                     // "claude" | "opencode" | "cursor" | …
  reserved: string[];             // absolute (root-relative) paths, never written
  project(src: Record<string, unknown>): NativeArtifact[];
}

/**
 * Write `content` to `path` (relative to repo root).
 * Creates parent dirs, stamps banner + LF, idempotent.
 */
export function writeGenerated(root: string, relPath: string, content: string): void {
  const abs = join(root, relPath);
  mkdirSync(join(abs, ".."), { recursive: true });

  // Strip any trailing whitespace the caller may have added, then append
  // exactly one \n. This normalizes all written content so that re-reading
  // produces a stable baseline — making writeGenerated idempotent across
  // runs regardless of whether the source JSON ends with \n or not.
  const normalized = content.replace(/\s+$/, "") + "\n";
  writeFileSync(abs, normalized, "utf-8");
}

/** Read a generated file, normalizing trailing whitespace for comparison. */
export function readGenerated(root: string, relPath: string): string {
  const abs = join(root, relPath);
  if (!existsSync(abs)) return "";
  return readFileSync(abs, "utf-8").replace(/\s+$/, "");
}
